import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Civilização do Tipo Intensivo do Leste Asiático","description":"","frontmatter":{},"headers":[],"relativePath":"pt/31-东亚集约型文明.md","filePath":"pt/31-东亚集约型文明.md","lastUpdated":null}'),t={name:"pt/31-东亚集约型文明.md"};function d(n,o,r,c,l,m){return e(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="civilizacao-do-tipo-intensivo-do-leste-asiatico" tabindex="-1">Civilização do Tipo Intensivo do Leste Asiático <a class="header-anchor" href="#civilizacao-do-tipo-intensivo-do-leste-asiatico" aria-label="Permalink to &quot;Civilização do Tipo Intensivo do Leste Asiático&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>31</td></tr><tr><td>Módulo</td><td>Tipologia de Civilização e Sistema Social</td></tr><tr><td>Palavras-chave principais</td><td>Intensivo do Leste Asiático, Coletivo优先, Cultivo em larga escala, Execução eficiente, Herança familiar</td></tr></tbody></table><h2 id="i-origem-e-filosofia-central-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" tabindex="-1">I. Origem e Filosofia Central da Civilização do Tipo Intensivo do Leste Asiático <a class="header-anchor" href="#i-origem-e-filosofia-central-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" aria-label="Permalink to &quot;I. Origem e Filosofia Central da Civilização do Tipo Intensivo do Leste Asiático&quot;">​</a></h2><p>A civilização do tipo intensivo do Leste Asiático é a mais coletivista entre os cinco tipos de civilização simbiótica, e sua origem pode ser rastreada até a tradição civilizacional de milhares de anos na região do Leste Asiático no mundo real. Na região do Leste Asiático, durante o longo desenvolvimento histórico, formaram-se características civilizacionais centradas no coletivo, baseadas na família como unidade e fundamentadas na ordem. Após o estabelecimento da civilização simbiótica de âncoras, essa tradição combinou-se com a filosofia simbiótica para criar a forma civilizacional única da &quot;civilização do tipo intensivo do Leste Asiático&quot;.</p><p>A filosofia central da civilização do tipo intensivo do Leste Asiático pode ser resumida em oito caracteres: &quot;coletivo优先, intensivo e eficiente&quot;. Especificamente:</p><ol><li><strong>Coletivo优先</strong>: Na relação entre indivíduo e coletivo, enfatiza-se que o interesse coletivo está acima do interesse individual, e o desenvolvimento do indivíduo deve ser integrado ao desenvolvimento do coletivo. Unidades coletivas como famílias, seitas e comunidades são as células básicas da sociedade, e o indivíduo realiza seu próprio valor contribuindo para o coletivo</li><li><strong>Intensivo e eficiente</strong>: Na alocação de recursos, enfatiza-se a realização da utilização intensiva e da alocação eficiente de recursos por meio do planejamento coordenado coletivo. Opõe-se à construção repetida dispersa e de baixo nível, e defende a concentração de forças para realizar grandes empreendimentos</li><li><strong>Ordem e harmonia</strong>: Nas relações sociais, enfatiza-se a ordem social de hierarquia respeitosa e etiqueta por idade, buscando a convivência harmoniosa entre as pessoas</li><li><strong>Diligência e progresso</strong>: Nas qualidades individuais, venera-se o espírito de diligência, frugalidade, perseverança e progresso, acreditando que por meio de esforços incansáveis pode-se mudar o destino</li></ol><p>Essas filosofias da civilização do tipo intensivo do Leste Asiático高度 se alinham com a filosofia central da civilização simbiótica de âncoras: &quot;mais trabalho, mais ganho; auto-gerar e auto-crescer; todos têm um caminho; progresso comum de todas as raças&quot;. O coletivo优先 garante a realização do &quot;progresso comum de todas as raças&quot;, o intensivo e eficiente garante a eficiência do &quot;mais trabalho, mais ganho&quot;, e a diligência e progresso é a manifestação vívida do &quot;auto-gerar e auto-crescer&quot;.</p><h2 id="ii-estrutura-social-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" tabindex="-1">II. Estrutura Social da Civilização do Tipo Intensivo do Leste Asiático <a class="header-anchor" href="#ii-estrutura-social-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" aria-label="Permalink to &quot;II. Estrutura Social da Civilização do Tipo Intensivo do Leste Asiático&quot;">​</a></h2><p>A estrutura social da civilização do tipo intensivo do Leste Asiático adota o coletivo de três níveis &quot;família — seita — comunidade&quot; como estrutura básica, formando uma rede social aninhada camada por camada e intimamente conectada:</p><table tabindex="0"><thead><tr><th>Nível</th><th>Unidade</th><th>Escala</th><th>Função central</th><th>Método de alocação de recursos</th></tr></thead><tbody><tr><td>Primeiro nível</td><td>Família</td><td>Dezenas a centenas de pessoas</td><td>Garantia de vida básica, vínculo afetivo familiar, educação inicial</td><td>Distribuição conforme necessidade dentro da família</td></tr><tr><td>Segundo nível</td><td>Seita</td><td>Centenas a milhares de pessoas</td><td>Cultivo profissional, pesquisa e desenvolvimento tecnológico, gestão de recursos</td><td>Distribuição conforme trabalho dentro da seita</td></tr><tr><td>Terceiro nível</td><td>Comunidade</td><td>Milhares a centenas de milhares de pessoas</td><td>Serviço público, infraestrutura básica, governança social</td><td>Coordenação comunitária + regulação de mercado</td></tr></tbody></table><h3 id="_2-1-familia" tabindex="-1">2.1 Família <a class="header-anchor" href="#_2-1-familia" aria-label="Permalink to &quot;2.1 Família&quot;">​</a></h3><p>A família é a unidade social mais básica da civilização do tipo intensivo do Leste Asiático, geralmente composta por dezenas a centenas de pessoas relacionadas por sangue. A família assume as seguintes funções centrais:</p><ul><li><strong>Garantia de vida básica</strong>: Os membros da família se ajudam mutuamente, garantindo que as necessidades básicas de vida de cada membro sejam atendidas</li><li><strong>Vínculo afetivo familiar</strong>: Por meio de atividades como rituais familiares e reuniões familiares, mantém-se o vínculo emocional entre os membros</li><li><strong>Educação inicial</strong>: Os mais velhos da família são responsáveis pela educação inicial dos mais jovens, incluindo conhecimentos básicos, iniciação ao cultivo, cultivo moral, etc.</li><li><strong>Acúmulo de recursos</strong>: A família acumula coletivamente riqueza e recursos de cultivo, apoiando o desenvolvimento dos membros da família</li></ul><p>A alocação de recursos dentro da família segue o princípio combinado de &quot;distribuição conforme necessidade + distribuição conforme trabalho&quot; — as necessidades básicas de vida são distribuídas conforme necessidade, e os recursos de cultivo adicionais e recompensas são distribuídos conforme a contribuição individual para a família.</p><h3 id="_2-2-seita" tabindex="-1">2.2 Seita <a class="header-anchor" href="#_2-2-seita" aria-label="Permalink to &quot;2.2 Seita&quot;">​</a></h3><p>A seita é a unidade central responsável pelo cultivo profissional e pesquisa e desenvolvimento tecnológico na civilização do tipo intensivo do Leste Asiático, geralmente composta por centenas a milhares de pessoas com a mesma direção de cultivo ou especialização tecnológica. As funções centrais da seita incluem:</p><ul><li><strong>Cultivo profissional</strong>: A seita possui um sistema de cultivo completo e uma equipe de mentores, responsável pelo cultivo profissional sistemático dos discípulos</li><li><strong>Pesquisa e desenvolvimento tecnológico</strong>: A seita concentra forças para realizar pesquisa e inovação em tecnologias de cultivo e engenharia</li><li><strong>Gestão de recursos</strong>: A seita obtém renda por meio da gestão de recursos de cultivo, prestação de serviços tecnológicos, etc., apoiando o funcionamento e desenvolvimento da seita</li><li><strong>Saída de talentos</strong>: Os talentos excelentes formados pela seita podem entrar em instituições de nível mais alto, contribuindo para o desenvolvimento da comunidade e da civilização</li></ul><p>A alocação de recursos dentro da seita segue principalmente o princípio da &quot;distribuição conforme trabalho&quot; — os discípulos obtêm a alocação de recursos correspondente com base em seus resultados de cultivo e contribuição para a seita. A seita geralmente possui um sistema hierárquico rigoroso, desde discípulos externos, discípulos internos, discípulos centrais até anciãos e mestre supremo — com hierarquia clara e promoção ordenada.</p><h3 id="_2-3-comunidade" tabindex="-1">2.3 Comunidade <a class="header-anchor" href="#_2-3-comunidade" aria-label="Permalink to &quot;2.3 Comunidade&quot;">​</a></h3><p>A comunidade é a unidade social de mais alto nível na civilização do tipo intensivo do Leste Asiático, geralmente composta por milhares a centenas de milhares de pessoas, cobrindo uma determinada área geográfica. As funções centrais da comunidade incluem:</p><ul><li><strong>Serviço público</strong>: Fornecer serviços públicos como educação, saúde, moradia, meio ambiente, etc.</li><li><strong>Infraestrutura básica</strong>: Construir e manter infraestruturas básicas como âncoras, canais de energia, redes de transporte, etc.</li><li><strong>Governança social</strong>: Manter a ordem social, mediar disputas, executar leis</li><li><strong>Coordenação de recursos</strong>: Coordenar os recursos de cultivo dentro da jurisdição, realizar alocação macroscópica de recursos</li></ul><p>A alocação de recursos no nível comunitário segue o princípio da &quot;coordenação + mercado&quot; — os recursos públicos básicos são alocados de forma coordenada pela comunidade, e os recursos não básicos são regulados por meio do mecanismo de mercado.</p><h2 id="iii-modo-de-cultivo-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" tabindex="-1">III. Modo de Cultivo da Civilização do Tipo Intensivo do Leste Asiático <a class="header-anchor" href="#iii-modo-de-cultivo-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" aria-label="Permalink to &quot;III. Modo de Cultivo da Civilização do Tipo Intensivo do Leste Asiático&quot;">​</a></h2><p>O modo de cultivo da civilização do tipo intensivo do Leste Asiático tem como características centrais &quot;em larga escala, padronizado e sistematizado&quot;, sendo capaz de formar um grande número de cultivadores qualificados em curto prazo:</p><h3 id="_3-1-cultivo-em-larga-escala" tabindex="-1">3.1 Cultivo em larga escala <a class="header-anchor" href="#_3-1-cultivo-em-larga-escala" aria-label="Permalink to &quot;3.1 Cultivo em larga escala&quot;">​</a></h3><p>A civilização do tipo intensivo do Leste Asiático é boa no cultivo de talentos em larga escala por meio do sistema de seitas. Uma grande seita pode cultivar simultaneamente milhares de discípulos, e por meio de um sistema de currículos padronizado e um modelo de ensino em linha de montagem, realiza a produção em larga escala de talentos de cultivo. As vantagens desse modelo de cultivo são alta eficiência, ampla cobertura e capacidade de melhorar rapidamente o nível geral de cultivo.</p><h3 id="_3-2-sistema-padronizado" tabindex="-1">3.2 Sistema padronizado <a class="header-anchor" href="#_3-2-sistema-padronizado" aria-label="Permalink to &quot;3.2 Sistema padronizado&quot;">​</a></h3><p>A civilização do tipo intensivo do Leste Asiático valoriza a construção padronizada do sistema de cultivo. Os trezentos conjuntos de sistemas de cultivo de origem, após serem introduzidos na civilização do tipo intensivo do Leste Asiático, geralmente são posteriormente detalhados em materiais didáticos de cultivo padronizados, programas de ensino e critérios de avaliação. Cada estágio de cultivo tem objetivos, conteúdos e métodos de avaliação claros, garantindo a estabilidade da qualidade do cultivo.</p><h3 id="_3-3-heranca-mestre-discipulo" tabindex="-1">3.3 Herança mestre-discípulo <a class="header-anchor" href="#_3-3-heranca-mestre-discipulo" aria-label="Permalink to &quot;3.3 Herança mestre-discípulo&quot;">​</a></h3><p>Embora enfatize a larga escala e a padronização, a civilização do tipo intensivo do Leste Asiático ainda valoriza muito a herança mestre-discípulo. Cada discípulo, após o ingresso, recebe um mentor, que é responsável pela orientação diária e cultivo moral do discípulo. Para discípulos com talentos excepcionais, eles ainda são aceitos como &quot;discípulos diretos&quot;, recebendo orientação cuidadosa um a um do mentor. Essa combinação de &quot;larga escala + personalização&quot; não apenas garante a eficiência do cultivo, mas também considera o desenvolvimento personalizado dos talentos.</p><h3 id="_3-4-avaliacao-e-promocao" tabindex="-1">3.4 Avaliação e promoção <a class="header-anchor" href="#_3-4-avaliacao-e-promocao" aria-label="Permalink to &quot;3.4 Avaliação e promoção&quot;">​</a></h3><p>A civilização do tipo intensivo do Leste Asiático estabeleceu um rigoroso sistema de avaliação e promoção. Os discípulos precisam participar regularmente de avaliações, e o conteúdo da avaliação inclui nível de cultivo, capacidade de combate real, conhecimento teórico, cultivo moral, etc. Aqueles que passam na avaliação podem ser promovidos de nível, obtendo mais alocação de recursos e status mais alto; aqueles que não passam precisam repetir o ano, ou até mesmo ser eliminados. Esse sistema não apenas incentiva o espírito de progresso dos discípulos, mas também garante a qualidade da formação de talentos.</p><h2 id="iv-mecanismo-de-producao-contratual-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" tabindex="-1">IV. Mecanismo de Produção Contratual da Civilização do Tipo Intensivo do Leste Asiático <a class="header-anchor" href="#iv-mecanismo-de-producao-contratual-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" aria-label="Permalink to &quot;IV. Mecanismo de Produção Contratual da Civilização do Tipo Intensivo do Leste Asiático&quot;">​</a></h2><p>O mecanismo de produção contratual da civilização do tipo intensivo do Leste Asiático adota o &quot;contrato coletivo&quot; como forma principal, o que é claramente diferente de outros tipos:</p><ol><li><strong>Unidade contratual</strong>: Adota unidades coletivas como famílias e seitas como sujeitos contratuais, em vez de indivíduos como sujeitos contratuais</li><li><strong>Conteúdo contratual</strong>: As unidades coletivas contratam tarefas como desenvolvimento de recursos de cultivo, manutenção de âncoras, pesquisa e desenvolvimento tecnológico em determinadas áreas junto à comunidade</li><li><strong>Distribuição interna</strong>: Após as unidades coletivas obterem a receita contratual, realizam uma segunda distribuição interna, considerando tanto o acúmulo coletivo quanto o retorno individual</li><li><strong>Responsabilidade conjunta</strong>: Os membros dentro das unidades coletivas assumem responsabilidade conjunta uns com os outros — o excelente desempenho de uma pessoa pode trazer recompensas para o coletivo, e a violação de regras de uma pessoa também pode afetar a classificação do coletivo</li></ol><p>As vantagens desse mecanismo de &quot;contrato coletivo&quot; são que ele pode exercer o efeito de escala e as vantagens de colaboração do coletivo, melhorando a eficiência de utilização de recursos; ao mesmo tempo, também fortalece a coesão do coletivo e o senso de pertencimento dos membros.</p><h2 id="v-vantagens-e-desafios-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" tabindex="-1">V. Vantagens e Desafios da Civilização do Tipo Intensivo do Leste Asiático <a class="header-anchor" href="#v-vantagens-e-desafios-da-civilizacao-do-tipo-intensivo-do-leste-asiatico" aria-label="Permalink to &quot;V. Vantagens e Desafios da Civilização do Tipo Intensivo do Leste Asiático&quot;">​</a></h2><h3 id="_5-1-vantagens-tipicas" tabindex="-1">5.1 Vantagens típicas <a class="header-anchor" href="#_5-1-vantagens-tipicas" aria-label="Permalink to &quot;5.1 Vantagens típicas&quot;">​</a></h3><ul><li><strong>Forte capacidade de execução</strong>: A tradição coletivista e o rigoroso sistema hierárquico garantem que as decisões possam ser executadas de forma rápida e eficiente</li><li><strong>Alta eficiência</strong>: A alocação intensiva de recursos e o cultivo de talentos em larga escala实现aram alta eficiência de desenvolvimento</li><li><strong>Forte coesão</strong>: A conexão estreita entre famílias e seitas formou uma forte coesão social</li><li><strong>Alta estabilidade</strong>: A estrutura social ordenada e as relações interpessoais harmoniosas garantiram a estabilidade social a longo prazo</li></ul><h3 id="_5-2-desafios-enfrentados" tabindex="-1">5.2 Desafios enfrentados <a class="header-anchor" href="#_5-2-desafios-enfrentados" aria-label="Permalink to &quot;5.2 Desafios enfrentados&quot;">​</a></h3><ul><li><strong>Espaço individual insuficiente</strong>: A ênfase excessiva no coletivo pode comprimir o espaço livre do indivíduo, afetando a criatividade e a diversidade individuais</li><li><strong>Motivação inovadora fraca</strong>: O modelo de cultivo padronizado pode limitar o pensamento inovador, sendo necessário encontrar um equilíbrio entre norma e inovação</li><li><strong>Risco de solidificação hierárquica</strong>: Se o rigoroso sistema hierárquico carecer de mecanismo de mobilidade, pode levar à solidificação de classes</li><li><strong>Maior pressão competitiva</strong>: O intenso mecanismo de avaliação e promoção pode trazer maior pressão psicológica para o indivíduo</li></ul><p>Diante desses desafios, a civilização do tipo intensivo do Leste Asiático está absorvendo ativamente as vantagens de outros tipos, como a introdução do mecanismo de incentivo à inovação do tipo pluralista da América do Norte, o sistema de apoio psicológico do tipo de bem-estar nórdico, etc., otimizando continuamente seu próprio design institucional.</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A civilização do tipo intensivo do Leste Asiático é o tipo de civilização mais coletivista na civilização simbiótica de âncoras. Com a filosofia central de &quot;coletivo优先, intensivo e eficiente&quot;, por meio da estrutura social de três níveis família — seita — comunidade, do modo de cultivo em larga escala e padronizado, e do mecanismo de produção de contrato coletivo,实现ou desenvolvimento eficiente e forte coesão. Ao manter suas próprias características, a civilização do tipo intensivo do Leste Asiático também está absorvendo continuamente as vantagens de outros tipos, desenvolvendo-se em uma direção mais equilibrada e inclusiva.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Visão Geral dos Cinco Tipos de Civilização Simbiótica)</li><li>36-社会结构与阶层流动 (Estrutura Social e Mobilidade de Classes)</li><li>37-共生教育体系 (Sistema de Educação Simbiótica)</li></ul>',46)])])}const p=a(t,[["render",d]]);export{v as __pageData,p as default};
